// Initialize users database, cart, wishlist, and orders
(function initStorage() {
  if (typeof localStorage === 'undefined') return;
  if (!localStorage.getItem(STORAGE_KEYS.USERS_DB)) {
    localStorage.setItem(STORAGE_KEYS.USERS_DB, JSON.stringify([DEFAULT_USER]));
  }
  // NOTE: STORAGE_KEYS.USER is NOT automatically set on initial load!
  // This ensures unauthenticated visitors see index.html (Halaman Pembuka).
  if (!localStorage.getItem(STORAGE_KEYS.ORDERS)) {
    localStorage.setItem(STORAGE_KEYS.ORDERS, JSON.stringify(DEFAULT_ORDERS));
  }
  if (!localStorage.getItem(STORAGE_KEYS.WISHLIST)) {
    localStorage.setItem(STORAGE_KEYS.WISHLIST, JSON.stringify([]));
  }
  if (!localStorage.getItem(STORAGE_KEYS.CART)) {
    localStorage.setItem(STORAGE_KEYS.CART, JSON.stringify([]));
  }
  if (!localStorage.getItem(STORAGE_KEYS.CHECKOUT_INFO)) {
    localStorage.setItem(STORAGE_KEYS.CHECKOUT_INFO, JSON.stringify(DEFAULT_CHECKOUT_DATA));
  }
})();

// ==========================================
// AUTH PROTECTION HELPERS
// ==========================================
function checkAuthProtection(page) {
  if (typeof window === 'undefined') return;
  const user = getCurrentUser();
  const urlParams = new URLSearchParams(window.location.search);

  if (page === 'welcome') {
    // If user is already logged in, redirect directly to home.html unless explicit ?preview=1
    if (user && !urlParams.has('preview')) {
      window.location.replace('home.html');
      return;
    }
  } else if (page === 'login' || page === 'register') {
    // If already logged in, redirect to home.html
    if (user) {
      window.location.replace('home.html');
      return;
    }
  } else if (page === 'cs') {
    // Customer Service is accessible to all users (both guests and registered members)
    return;
  } else {
    // Protected pages: home, detail, cart, checkout, payment, profile, wishlist
    if (!user) {
      sessionStorage.setItem('gadgetid_redirect_after_login', window.location.href);
      window.location.replace('index.html?auth=required&target=' + encodeURIComponent(page));
      return;
    }
  }
}

function logoutUser() {
  setCurrentUser(null);
  showToast('👋', 'Anda telah berhasil keluar dari akun.');
  setTimeout(() => {
    window.location.href = 'index.html';
  }, 600);
}

// ==========================================
// UTILITY FUNCTIONS
// ==========================================
function formatRp(num) {
  if (num === null || num === undefined || isNaN(num)) return 'Rp 0';
  return 'Rp ' + Number(num).toLocaleString('id-ID');
}

function showToast(icon, message) {
  let toast = document.getElementById('gadgetToast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'gadgetToast';
    toast.className = 'toast';
    toast.innerHTML = '<span class="toast-icon" id="gadgetToastIcon">✅</span><span id="gadgetToastMsg"></span>';
    document.body.appendChild(toast);
  }
  const iconEl = document.getElementById('gadgetToastIcon');
  const msgEl = document.getElementById('gadgetToastMsg');
  if (iconEl) iconEl.textContent = icon || 'ℹ️';
  if (msgEl) msgEl.textContent = message || '';
  toast.classList.add('show');
  clearTimeout(window._toastTimeout);
  window._toastTimeout = setTimeout(() => {
    toast.classList.remove('show');
  }, 3200);
}

// ==========================================
// CART FUNCTIONS
// ==========================================
function getCart() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEYS.CART)) || [];
  } catch (e) {
    return [];
  }
}

function saveCart(cart) {
  localStorage.setItem(STORAGE_KEYS.CART, JSON.stringify(cart));
  updateNavBadges();
}

function addToCart(productId, options = {}) {
  const p = products.find(item => item.id === productId);
  if (!p) return;
  const cart = getCart();

  const color = options.color || (p.colors && p.colors[0]) || '';
  const storage = options.storage || (p.storageOpts && p.storageOpts[0]) || p.storage || '';
  const extraPrice = (p.storagePrice && p.storagePrice[storage]) || 0;
  const finalPrice = p.price + extraPrice;
  const qty = options.qty || 1;

  let variantLabel = '';
  if (color && storage) variantLabel = color + ' · ' + storage;
  else if (color) variantLabel = color;
  else if (storage) variantLabel = storage;

  const cartKey = p.id + '_' + color + '_' + storage;
  const existing = cart.find(item => item.cartKey === cartKey);

  if (existing) {
    existing.qty += qty;
  } else {
    cart.push({
      cartKey: cartKey,
      id: p.id,
      name: p.name,
      brand: p.brand,
      category: p.category,
      price: finalPrice,
      originalPrice: p.oldPrice ? p.oldPrice + extraPrice : finalPrice,
      color: color,
      storage: storage,
      variantLabel: variantLabel,
      img: p.img,
      qty: qty
    });
  }

  saveCart(cart);
  showToast('🛒', p.name + ' (' + (variantLabel || 'Original') + ') ditambahkan ke keranjang!');
}

function removeFromCart(cartKey) {
  let cart = getCart();
  cart = cart.filter(item => item.cartKey !== cartKey);
  saveCart(cart);
  showToast('🗑', 'Produk dihapus dari keranjang.');
}

function updateCartQty(cartKey, delta) {
  let cart = getCart();
  const item = cart.find(i => i.cartKey === cartKey);
  if (item) {
    item.qty = Math.max(1, item.qty + delta);
    saveCart(cart);
  }
}

function getCartCount() {
  return getCart().reduce((sum, item) => sum + item.qty, 0);
}

function getCartTotal() {
  return getCart().reduce((sum, item) => sum + item.price * item.qty, 0);
}

// ==========================================
// WISHLIST FUNCTIONS
// ==========================================
function getWishlist() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEYS.WISHLIST)) || [];
  } catch (e) {
    return [];
  }
}

function saveWishlist(list) {
  localStorage.setItem(STORAGE_KEYS.WISHLIST, JSON.stringify(list));
  updateNavBadges();
}

function toggleWishlist(productId) {
  let list = getWishlist();
  const idx = list.indexOf(productId);
  const p = products.find(item => item.id === productId);
  const name = p ? p.name : 'Produk';

  if (idx > -1) {
    list.splice(idx, 1);
    saveWishlist(list);
    showToast('🤍', name + ' dihapus dari Wishlist.');
    return false;
  } else {
    list.push(productId);
    saveWishlist(list);
    showToast('❤️', name + ' ditambahkan ke Wishlist!');
    return true;
  }
}

function isInWishlist(productId) {
  return getWishlist().includes(productId);
}

function getWishlistCount() {
  return getWishlist().length;
}

// ==========================================
// USER & AUTH FUNCTIONS
// ==========================================
function getCurrentUser() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEYS.USER));
  } catch (e) {
    return null;
  }
}

function setCurrentUser(user) {
  if (user) {
    localStorage.setItem(STORAGE_KEYS.USER, JSON.stringify(user));
  } else {
    localStorage.removeItem(STORAGE_KEYS.USER);
  }
  updateNavBadges();
}

function getUsersDB() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS_DB)) || [DEFAULT_USER];
  } catch (e) {
    return [DEFAULT_USER];
  }
}

function saveUsersDB(db) {
  localStorage.setItem(STORAGE_KEYS.USERS_DB, JSON.stringify(db));
}

function loginUser(email, password) {
  const users = getUsersDB();
  const found = users.find(u => u.email.toLowerCase() === email.trim().toLowerCase() && u.password === password);
  if (found) {
    setCurrentUser(found);
    return { success: true, user: found };
  }
  return { success: false, message: 'Email atau kata sandi tidak sesuai!' };
}

function registerUser(userData) {
  const users = getUsersDB();
  const exists = users.find(u => u.email.toLowerCase() === userData.email.trim().toLowerCase());
  if (exists) {
    return { success: false, message: 'Email sudah terdaftar. Silakan gunakan email lain atau masuk.' };
  }
  const newUser = {
    id: 'USR-' + Math.floor(1000 + Math.random() * 9000),
    name: userData.name,
    email: userData.email,
    phone: userData.phone || '081234567890',
    password: userData.password,
    gender: 'Lainnya',
    birthDate: '',
    address: 'Belum diatur',
    city: 'Jakarta',
    province: 'DKI Jakarta',
    postalCode: '10110',
    avatar: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&h=150&fit=crop',
    memberTier: 'New Member',
    joinDate: new Date().toLocaleDateString('id-ID', { day:'numeric', month:'long', year:'numeric' })
  };
  users.push(newUser);
  saveUsersDB(users);
  setCurrentUser(newUser);
  return { success: true, user: newUser };
}

function logoutUser() {
  setCurrentUser(null);
  showToast('👋', 'Anda telah berhasil keluar dari akun.');
  setTimeout(() => {
    window.location.href = 'index.html';
  }, 600);
}

function updateUserProfile(updatedFields) {
  let current = getCurrentUser();
  if (!current) return false;
  current = { ...current, ...updatedFields };
  setCurrentUser(current);

  const users = getUsersDB();
  const idx = users.findIndex(u => u.id === current.id);
  if (idx > -1) {
    users[idx] = current;
    saveUsersDB(users);
  }
  return true;
}

function changeUserPassword(oldPassword, newPassword) {
  const current = getCurrentUser();
  if (!current) return { success: false, message: 'Silakan masuk terlebih dahulu.' };
  if (current.password !== oldPassword) {
    return { success: false, message: 'Kata sandi saat ini tidak cocok!' };
  }
  if (!newPassword || newPassword.length < 6) {
    return { success: false, message: 'Kata sandi baru minimal 6 karakter!' };
  }
  current.password = newPassword;
  setCurrentUser(current);

  const users = getUsersDB();
  const idx = users.findIndex(u => u.id === current.id);
  if (idx > -1) {
    users[idx].password = newPassword;
    saveUsersDB(users);
  }
  return { success: true, message: 'Kata sandi berhasil diperbarui!' };
}

// ==========================================
// ORDERS
// ==========================================
function getOrders() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEYS.ORDERS)) || [];
  } catch (e) {
    return [];
  }
}

function saveOrders(orders) {
  localStorage.setItem(STORAGE_KEYS.ORDERS, JSON.stringify(orders));
}

function createOrder(orderData) {
  const orders = getOrders();
  const orderId = '#GDT-' + Math.floor(100000 + Math.random() * 900000);
  const now = new Date();
  const dateStr = now.toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });

  const newOrder = {
    id: orderId,
    date: dateStr,
    status: 'Diproses',
    statusColor: '#F59E0B',
    paymentMethod: orderData.paymentMethod || 'Transfer Bank',
    shippingCourier: orderData.shippingCourier || 'J&T Express',
    customer: orderData.customer || {},
    items: orderData.items || getCart(),
    subtotal: orderData.subtotal || getCartTotal(),
    shippingCost: 0,
    discount: orderData.discount || 0,
    total: orderData.total || getCartTotal()
  };

  orders.unshift(newOrder);
  saveOrders(orders);
  saveCart([]);
  return newOrder;
}

