function renderFloatingCS(activePage = '') {
  if (typeof document === 'undefined') return;

  const currentPath = typeof window !== 'undefined' ? (window.location.pathname || '') : '';
  const isCsPage = activePage === 'cs' || currentPath.toLowerCase().endsWith('cs.html');

  // Clean up existing element if present
  const existing = document.getElementById('globalFloatingCS');
  if (existing) {
    if (typeof existing.remove === 'function') {
      existing.remove();
    } else if (existing.parentNode) {
      existing.parentNode.removeChild(existing);
    }
  }

  // Do not show floating button on cs.html itself
  if (isCsPage) return;

  // Defer if document.body is not ready
  if (!document.body) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', () => renderFloatingCS(activePage));
    }
    return;
  }

  // Build the floating Customer Service button
  const csBtn = document.createElement('a');
  csBtn.href = 'cs.html';
  csBtn.id = 'globalFloatingCS';
  csBtn.className = 'global-floating-cs';
  csBtn.setAttribute('title', 'Tanya Customer Service & Live Chat 24 Jam');
  csBtn.setAttribute('aria-label', 'Customer Service Gadget.Id');
  csBtn.innerHTML = [
    '<span class="floating-cs-badge"><span class="cs-pulse-dot"></span>Online</span>',
    '<span class="floating-cs-icon">💬</span>',
    '<span class="floating-cs-text">Tanya CS</span>'
  ].join('');

  document.body.appendChild(csBtn);
}

function updateNavBadges() {
  const cBadge = document.getElementById('navCartBadge');
  const wBadge = document.getElementById('navWishlistBadge');
  const dcBadge = document.getElementById('drawerCartBadge');
  const dwBadge = document.getElementById('drawerWishlistBadge');
  const cCount = getCartCount();
  const wCount = getWishlistCount();
  if (cBadge) cBadge.textContent = cCount;
  if (wBadge) wBadge.textContent = wCount;
  if (dcBadge) dcBadge.textContent = cCount;
  if (dwBadge) dwBadge.textContent = wCount;
}

function toggleMobileNav(event) {
  if (event) event.stopPropagation();
  const drawer = document.getElementById('mobileNavDrawer');
  const backdrop = document.getElementById('mobileNavBackdrop');
  const btn = document.getElementById('navHamburgerBtn');
  if (drawer && backdrop) {
    const isOpen = drawer.classList.contains('open');
    if (isOpen) {
      closeMobileNav();
    } else {
      drawer.classList.add('open');
      backdrop.classList.add('open');
      if (btn) btn.classList.add('active');
      if (document.body) document.body.style.overflow = 'hidden';
    }
  }
}

function closeMobileNav() {
  const drawer = document.getElementById('mobileNavDrawer');
  const backdrop = document.getElementById('mobileNavBackdrop');
  const btn = document.getElementById('navHamburgerBtn');
  if (drawer) drawer.classList.remove('open');
  if (backdrop) backdrop.classList.remove('open');
  if (btn) btn.classList.remove('active');
  if (document.body) document.body.style.overflow = '';
}

function toggleUserMenu(event) {
  event.stopPropagation();
  const menu = document.getElementById('userDropdownMenu');
  if (menu) menu.classList.toggle('show');
}

if (typeof document !== 'undefined') {
  document.addEventListener('click', () => {
    const menu = document.getElementById('userDropdownMenu');
    if (menu) menu.classList.remove('show');
  });

  if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
    window.addEventListener('resize', () => {
      if (window.innerWidth > 900) closeMobileNav();
    });
    window.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') closeMobileNav();
    });
  }

  const ensureFloatingCS = () => {
    const isCs = typeof window !== 'undefined' && (window.location.pathname || '').toLowerCase().endsWith('cs.html');
    if (!isCs && !document.getElementById('globalFloatingCS') && document.body) {
      renderFloatingCS();
    }
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', ensureFloatingCS);
  } else {
    setTimeout(ensureFloatingCS, 50);
  }
}

// ==========================================
// SEARCH MODAL LOGIC
// ==========================================
function openSearchModal() {
  const modal = document.getElementById('searchModalOverlay');
  if (modal) {
    modal.classList.add('open');
    const input = document.getElementById('globalSearchInput');
    if (input) {
      input.focus();
      handleGlobalSearch(input.value);
    }
  }
}

function closeSearchModal() {
  const modal = document.getElementById('searchModalOverlay');
  if (modal) modal.classList.remove('open');
}

function handleSearchOverlayClick(e) {
  if (e.target.id === 'searchModalOverlay') closeSearchModal();
}

function quickSearch(tag) {
  const input = document.getElementById('globalSearchInput');
  if (input) {
    input.value = tag;
    handleGlobalSearch(tag);
  }
}

function handleSearchKeydown(e) {
  if (e.key === 'Escape') {
    closeSearchModal();
  } else if (e.key === 'Enter') {
    const val = document.getElementById('globalSearchInput').value.trim();
    if (val) {
      window.location.href = 'home.html?search=' + encodeURIComponent(val);
    }
  }
}

function handleGlobalSearch(query) {
  const list = document.getElementById('searchResultsList');
  if (!list) return;
  const q = query.trim().toLowerCase();
  if (!q) {
    list.innerHTML = '<div class="search-empty-hint">Ketik minimal 1 karakter untuk mulai mencari gadget terbaik...</div>';
    return;
  }

  const matches = products.filter(p =>
    p.name.toLowerCase().includes(q) ||
    p.brand.toLowerCase().includes(q) ||
    p.category.toLowerCase().includes(q) ||
    (p.storage && p.storage.toLowerCase().includes(q))
  );

  if (!matches.length) {
    list.innerHTML = '<div class="search-no-results"><span>🔍</span><p>Tidak ada produk yang cocok dengan "' + query + '"</p><small>Coba gunakan kata kunci lain seperti iPhone, Samsung, AirPods, Kabel</small></div>';
    return;
  }

  list.innerHTML = matches.slice(0, 8).map(p => [
    '<a href="product-detail.html?id=' + p.id + '" class="search-result-item">',
    '  <img src="' + p.img + '" alt="' + p.name + '" class="search-result-img" onerror="this.src=\'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=80&h=80&fit=crop\'">',
    '  <div class="search-result-info">',
    '    <div class="search-result-brand">' + p.brand + ' · ' + p.category.toUpperCase() + '</div>',
    '    <div class="search-result-name">' + p.name + '</div>',
    '    <div class="search-result-price">' + formatRp(p.price) + (p.oldPrice ? ' <span class="old-price">' + formatRp(p.oldPrice) + '</span>' : '') + '</div>',
    '  </div>',
    '  <span class="search-result-arrow">→</span>',
    '</a>'
  ].join('\n')).join('');
}

if (typeof document !== 'undefined') {
  document.addEventListener('keydown', (e) => {
    if ((e.ctrlKey && e.key === 'k') || (e.key === '/' && !['INPUT', 'TEXTAREA'].includes(document.activeElement.tagName))) {
      e.preventDefault();
      openSearchModal();
    }
  });
}

